// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// DevLogin Development sign-in that creates the user on first use. Answers 404 unless DEV_LOGIN is on.
	// (POST /auth/dev-login)
	DevLogin(ctx context.Context, request DevLoginRequestObject) (DevLoginResponseObject, error)
	// GoogleSignIn Signs in with a Google ID token, or offers a signup if the Google account is new. Answers 404 unless Google sign-in is configured.
	// (POST /auth/google)
	GoogleSignIn(ctx context.Context, request GoogleSignInRequestObject) (GoogleSignInResponseObject, error)
	// GoogleSignup Creates the account for a verified Google identity, with the chosen username. Answers 404 unless Google sign-in is configured.
	// (POST /auth/google/signup)
	GoogleSignup(ctx context.Context, request GoogleSignupRequestObject) (GoogleSignupResponseObject, error)
	// RefreshSession Exchanges a refresh token for a new session (the old refresh token stops working).
	// (POST /auth/refresh)
	RefreshSession(ctx context.Context, request RefreshSessionRequestObject) (RefreshSessionResponseObject, error)
	// UsernameAvailable Whether a username can be chosen at signup. Answers 404 unless Google sign-in is configured.
	// (GET /auth/username-available)
	UsernameAvailable(ctx context.Context, request UsernameAvailableRequestObject) (UsernameAvailableResponseObject, error)
	// ListBodyWeights The signed-in user's weigh-ins, oldest first (at most 5000, the newest kept).
	// (GET /body-weights)
	ListBodyWeights(ctx context.Context, request ListBodyWeightsRequestObject) (ListBodyWeightsResponseObject, error)

	// (DELETE /body-weights/{date})
	DeleteBodyWeight(ctx context.Context, request DeleteBodyWeightRequestObject) (DeleteBodyWeightResponseObject, error)
	// SetBodyWeight Records (or replaces) the weigh-in for a local calendar day.
	// (PUT /body-weights/{date})
	SetBodyWeight(ctx context.Context, request SetBodyWeightRequestObject) (SetBodyWeightResponseObject, error)
	// SearchExercises Search the exercise catalog by name or alias.
	// (GET /exercises)
	SearchExercises(ctx context.Context, request SearchExercisesRequestObject) (SearchExercisesResponseObject, error)
	// GetLastSession The caller's sets from their most recent session of an exercise with this exact variant.
	// (GET /exercises/{id}/last)
	GetLastSession(ctx context.Context, request GetLastSessionRequestObject) (GetLastSessionResponseObject, error)
	// SearchGyms Search the shared gym directory.
	// (GET /gyms)
	SearchGyms(ctx context.Context, request SearchGymsRequestObject) (SearchGymsResponseObject, error)
	// CreateGym Adds a gym to the shared directory.
	// (POST /gyms)
	CreateGym(ctx context.Context, request CreateGymRequestObject) (CreateGymResponseObject, error)
	// DeleteMe Permanently deletes the account and everything it owns.
	// (DELETE /me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// GetMe The signed-in user's profile.
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Changes the display name, unit system or time zone. Absent or null fields are left as they are.
	// (PATCH /me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)

	// (DELETE /sets/{id})
	DeleteSet(ctx context.Context, request DeleteSetRequestObject) (DeleteSetResponseObject, error)
	// UpdateSet Omitted fields are unchanged; `null` is unchanged too, except for `rir`, which `null` clears.
	// (PATCH /sets/{id})
	UpdateSet(ctx context.Context, request UpdateSetRequestObject) (UpdateSetResponseObject, error)
	// GetStatsConsistency Activity per local day over the last weeks weeks, and week streaks over all history.
	// (GET /stats/consistency)
	GetStatsConsistency(ctx context.Context, request GetStatsConsistencyRequestObject) (GetStatsConsistencyResponseObject, error)
	// ListStatsExercises The exercises the user has logged a working set of, one row per variant, most recently performed first.
	// (GET /stats/exercises)
	ListStatsExercises(ctx context.Context, request ListStatsExercisesRequestObject) (ListStatsExercisesResponseObject, error)
	// GetStatsExerciseProgress One exercise's history, a point per session, with the records across them.
	// (GET /stats/exercises/{id}/progress)
	GetStatsExerciseProgress(ctx context.Context, request GetStatsExerciseProgressRequestObject) (GetStatsExerciseProgressResponseObject, error)
	// ListTags Every variation tag, by category then name.
	// (GET /tags)
	ListTags(ctx context.Context, request ListTagsRequestObject) (ListTagsResponseObject, error)
	// DeleteWorkoutExercise Removes the exercise and its sets.
	// (DELETE /workout-exercises/{id})
	DeleteWorkoutExercise(ctx context.Context, request DeleteWorkoutExerciseRequestObject) (DeleteWorkoutExerciseResponseObject, error)
	// AddSet Adds a set at the next position; `completed_at` defaults to now.
	// (POST /workout-exercises/{id}/sets)
	AddSet(ctx context.Context, request AddSetRequestObject) (AddSetResponseObject, error)
	// ListWorkouts The caller's workouts, newest first.
	// (GET /workouts)
	ListWorkouts(ctx context.Context, request ListWorkoutsRequestObject) (ListWorkoutsResponseObject, error)
	// CreateWorkout Starts a workout.
	// (POST /workouts)
	CreateWorkout(ctx context.Context, request CreateWorkoutRequestObject) (CreateWorkoutResponseObject, error)

	// (DELETE /workouts/{id})
	DeleteWorkout(ctx context.Context, request DeleteWorkoutRequestObject) (DeleteWorkoutResponseObject, error)

	// (GET /workouts/{id})
	GetWorkout(ctx context.Context, request GetWorkoutRequestObject) (GetWorkoutResponseObject, error)
	// UpdateWorkout Omitted or null fields are left unchanged; a field cannot be cleared.
	// (PATCH /workouts/{id})
	UpdateWorkout(ctx context.Context, request UpdateWorkoutRequestObject) (UpdateWorkoutResponseObject, error)
	// AddWorkoutExercise Adds an exercise (with its variation tags) at the next position.
	// (POST /workouts/{id}/exercises)
	AddWorkoutExercise(ctx context.Context, request AddWorkoutExerciseRequestObject) (AddWorkoutExerciseResponseObject, error)
	// FinishWorkout Ends the workout now. Finishing twice keeps the first end time.
	// (POST /workouts/{id}/finish)
	FinishWorkout(ctx context.Context, request FinishWorkoutRequestObject) (FinishWorkoutResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

